import{_ as e,o as a,c as o,a2 as l}from"./chunks/framework.CfwCq2QB.js";const r="/dev-go-docs/shots/0.2.5/zh-CN/light/options-models.png",g=JSON.parse('{"title":"AI 模型","description":"","frontmatter":{},"headers":[],"relativePath":"settings/models.md","filePath":"settings/models.md"}'),i={name:"settings/models.md"};function n(s,t,d,h,c,m){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="ai-模型" tabindex="-1">AI 模型 <a class="header-anchor" href="#ai-模型" aria-label="Permalink to &quot;AI 模型&quot;">​</a></h1><p>一句话：翻译引擎可选谷歌、微软（免翻墙）或任意 OpenAI 兼容大模型；翻译模型与对话模型分开配置——翻译选快的，解释和助手选强的。</p><h2 id="两个模型-各管一摊" tabindex="-1">两个模型，各管一摊 <a class="header-anchor" href="#两个模型-各管一摊" aria-label="Permalink to &quot;两个模型，各管一摊&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>用在哪</th><th>怎么选</th></tr></thead><tbody><tr><td><strong>翻译模型</strong></td><td>整页 / 悬停 / 划词翻译（引擎选「AI 大模型」时生效）</td><td>追求速度：不带深度思考的快模型，如 glm-5.3-flash、qwen-turbo、deepseek-chat</td></tr><tr><td><strong>对话模型</strong></td><td>划词解释 / 总结 / 润色、侧边栏 AI 助手</td><td>追求能力：支持工具调用的强模型，如 glm-5.3、Kimi K2、qwen3-max 或各家 Coding Plan</td></tr></tbody></table><p>对话模型默认沿用翻译模型的服务和 Key，单独保存过配置后独立生效；不想维护两套时可以「改回沿用翻译模型」。</p><p>沿用时，如果翻译用的是预设推荐的快模型，对话会自动换成该服务推荐的强模型（如智谱：翻译 glm-5.3-flash、对话 glm-5.3）；你自己选过别的模型则保持不变。给对话模型选预设时，也会直接填上推荐的强模型。</p><img src="'+r+'" alt="AI 模型设置"><p><em>图：设置页「AI 模型」——翻译模型与对话模型分开配置。</em></p><h2 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h2><p>三样东西：</p><ol><li><strong>服务预设</strong>：智谱 GLM、智谱 / Z.ai / 阿里云百炼 / 火山方舟各家 Coding Plan、通义千问、豆包、Ollama（本地）或自定义。选预设会自动填好接口地址</li><li><strong>接口地址（Base URL）</strong>：填到 <code>/v1</code> 即可，自动补全 <code>/chat/completions</code></li><li><strong>API Key</strong>：仅存本机，<strong>不进备份导出</strong>；本地 Ollama 可留空（需设置环境变量 <code>OLLAMA_ORIGINS=chrome-extension://*</code> 允许扩展访问）</li></ol><p><strong>模型</strong>一栏填好地址和 Key 后可以从列表选择（也支持自动获取模型列表）；「测试连接」一键验证配置是否可用。</p><h2 id="自定义要求-可选" tabindex="-1">自定义要求（可选） <a class="header-anchor" href="#自定义要求-可选" aria-label="Permalink to &quot;自定义要求（可选）&quot;">​</a></h2><p>可以给翻译和助手分别追加系统提示词：</p><ul><li>翻译：当术语表用，如「技术文档风格；Token 不翻译」</li><li>助手：定回答风格，如「回答尽量简短」「操作前先列出步骤」</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>Coding Plan 套餐 Key 只能配合专属接口地址使用；部分套餐条款限定在编程工具中使用，请留意</li><li>火山方舟的模型名填控制台里的模型 ID 或推理接入点 ID（<code>ep-xxxx</code>）</li><li>提示词会自动附带选中内容的段落上下文和网页标题，不用自己写进「自定义要求」</li></ul>',17)])])}const _=e(i,[["render",n]]);export{g as __pageData,_ as default};
